/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Integral, MatrixSymbol, Sym, kindOf, rational } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.matrices.kind", () => {
  it("A.kind", () => {
    expect(sympyStr(kindOf(new MatrixSymbol('A', rational(2), rational(2))))).toBe('MatrixKind(NumberKind)');
  });
  it("intM.kind", () => {
    const x = new Sym('x');
    expect(sympyStr(kindOf(new Integral([new MatrixSymbol('A', rational(2), rational(2)), x])))).toBe('MatrixKind(NumberKind)');
  });
});
